<template><ops-shell title="Trace history" description="Find linked business records by exact ID or transaction hash within your existing access scope." :tabs="tabs"><form class="ops-form ops-card" @submit.prevent="search"><label>{{ $t('Business type') }}<themed-select v-model="type" required><option v-for="t in types" :key="t.value" :value="t.value">{{ $t(t.label) }}</option></themed-select></label><label>{{ $t('Business reference') }}<input v-model.trim="reference" maxlength="100" pattern="[A-Za-z0-9_\-]+" required :placeholder="$t('Record ID, business ID or TX hash')"></label><div class="ops-actions"><button type="submit" class="ops-primary">{{ $t('Search') }}</button></div></form><p v-if="searched && !results.length" role="status">{{ $t('No matching record in your access scope') }}</p><section v-for="(item,i) in results" :key="i" class="ops-card"><h2>{{ $t('Business record') }}</h2><ops-fields :record="item.record"/><div class="ops-links"><Link v-for="link in item.links" :key="link.url" :href="link.url">{{ $t(link.label) }} ↗</Link></div><timeline :events="item.events"/></section></ops-shell></template>
<script>
import OpsShell from './Shell';import OpsFields from './Fields';import Timeline from './Timeline';
export default {components:{OpsShell,OpsFields,Timeline},props:{tabs:Array,types:Array,filters:Object,results:Array,searched:Boolean},data(){return {type:this.filters.type||(this.types[0]||{}).value,reference:this.filters.reference||''}},methods:{search(){this.$inertia.get(this.route('admin.operations.trace'),{type:this.type,reference:this.reference})}}};
</script>
